require_once __DIR__.'/includes/functions.php';require_role(['recipient','charity']);$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$q=$pdo->prepare("SELECT id,donor_id,status FROM food_donations WHERE id=?");$q->execute([$id]);$donation=$q->fetch();if(!$donation){http_response_code(404);exit('Listing not found.');}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$reason=trim($_POST['reason']??'');$description=trim($_POST['description']??'');if($reason===''||mb_strlen($reason)>120)$errors[]='Choose a reason.';if(!$errors){$pdo->prepare('INSERT INTO reports(reporter_id,donation_id,reason,description) VALUES(?,?,?,?)')->execute([current_user()['id'],$id,$reason,$description]);flash('success','Thank you. The listing was reported for review.');redirect('food-details.php?id='.$id);}}$page_title='Report listing | SharePlate';require __DIR__.'/includes/header.php';?>
<section class="form-section"><div class="form-card"><p class="eyebrow">Community safety</p><h1>Report this listing</h1><?php foreach($errors as $error):?><div class="alert alert-error"><?=e($error)?></div><?php endforeach;?><form method="post" class="stack-form"><?=csrf_field()?><label>Reason<select name="reason" required><option value="">Choose reason</option><?php foreach(['Inaccurate information','Unsafe food concern','Inappropriate content','Other'] as $r):?><option><?=e($r)?></option><?php endforeach;?></select></label><label>Details<textarea name="description" rows="4" maxlength="2000"></textarea></label><button class="button">Send report</button></form></div></section><?php require __DIR__.'/includes/footer.php';?>